posts.body:
Using ATT_Turan's code and comments in another thread for skipping params in the actor status window as a jumping off point, I want to hide certain actor parameters in the equip menu in rpg maker mz, which by default shows all actor parameters on the left-hand side. I have searched through threads, but there doesn't seem to be one dedicated to this for vanilla MZ.
The loop that draws the actor params in the equip menu, *I think* are these three items:
Window_EquipStatus.prototype.drawItem = function(x, y, paramId) {
const paramX = this.paramX();
const paramWidth = this.paramWidth();
const rightArrowWidth = this.rightArrowWidth();
this.drawParamName(x, y, paramId);
if (this._actor) {
this.drawCurrentParam(paramX, y, paramId);
}
this.drawRightArrow(paramX + paramWidth, y);
if (this._tempActor) {
this.drawNewParam(paramX + paramWidth + rightArrowWidth, y, paramId);
}
};
Window_EquipStatus.prototype.drawParamName = function(x, y, paramId) {
const width = this.paramX() - this.itemPadding() * 2;
this.changeTextColor(ColorManager.systemColor());
this.drawText(TextManager.param(paramId), x, y, width);
};
Window_EquipStatus.prototype.drawCurrentParam = function(x, y, paramId) {
const paramWidth = this.paramWidth();
this.resetTextColor();
this.drawText(this._actor.param(paramId), x, y, paramWidth, "right");
Click to expand...
