That causes erros rect, undefined etc.
Any suggestions are appreciated.

You would need to put it here.
Code:
Window_EquipStatus.prototype.drawAllParams = function() {
    for (let i = 0; i < 6; i++) {
        const x = this.itemPadding();
        let line = i;
        switch (i)
        {
        // List parameters to be skipped, subtracting 2 from the ID
            case 1:
            case 3:
            case 4:
            case 5:
                continue;
        // Else account for skipped lines
            case 2:
                line--;
                break;
        }
        let y = this.paramY(line);
        this.drawItem(x, y, 2 + i);
    }
};

